@startuml

class Well {
  + code : string
}

abstract class WellCategory {}

class OnshoreWell extends Well {
  + surfaceExtension : float
}

class OffshoreWell extends Well {
  + installationYear : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

class OnshoreWellCategory extends WellCategory {}
class OffshoreWellCategory extends WellCategory {}

Well "*" -- "1" WellCategory
OnshoreWell "1" -- "1" OnshoreWellCategory
OffshoreWell "1" -- "1" OffshoreWellCategory

Well "*" -- "*" OilCompany : extracts
Extraction "*" -- "1" Well
Extraction "*" -- "1" OilCompany

OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

